mkdir -p /app/output/assets && cat > /app/output/assets/styles.css <<'EOF'
:root {
  --bg: oklch(0.145 0.04 255);
  --bg-2: oklch(0.19 0.045 255);
  --panel: oklch(0.235 0.04 252 / 0.78);
  --panel-strong: oklch(0.27 0.045 252 / 0.92);
  --text: oklch(0.965 0.012 240);
  --muted: oklch(0.74 0.035 245);
  --soft: oklch(0.61 0.04 245);
  --primary: oklch(0.72 0.16 220);
  --primary-2: oklch(0.64 0.19 235);
  --teal: oklch(0.76 0.15 190);
  --green: oklch(0.75 0.17 145);
  --warning: oklch(0.83 0.14 75);
  --line: oklch(0.44 0.055 245 / 0.55);
  --line-strong: oklch(0.58 0.09 225 / 0.75);
  --shadow: 0 24px 80px oklch(0.06 0.02 255 / 0.42);
  --radius: 22px;
  --font: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --mono: "IBM Plex Mono", "SFMono-Regular", Consolas, monospace;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  color: var(--text);
  font-family: var(--font);
  background:
    radial-gradient(circle at 12% 4%, oklch(0.43 0.13 232 / 0.34), transparent 34rem),
    radial-gradient(circle at 84% 12%, oklch(0.52 0.13 185 / 0.22), transparent 30rem),
    linear-gradient(135deg, #0d1b2a 0%, #111f31 45%, #1b2838 100%);
  min-height: 100vh;
}
a { color: inherit; text-decoration: none; }
button, input, select, textarea { font: inherit; }
img, svg { max-width: 100%; }
.container { width: min(1180px, calc(100% - 36px)); margin-inline: auto; }

.skip-link { position: absolute; left: -999px; top: 12px; z-index: 100; background: var(--primary); color: #061523; padding: 10px 14px; border-radius: 999px; }
.skip-link:focus { left: 12px; }

.site-header {
  position: sticky; top: 0; z-index: 50;
  border-bottom: 1px solid oklch(0.58 0.08 225 / 0.18);
  background: oklch(0.145 0.04 255 / 0.8);
  backdrop-filter: blur(18px);
}
.navbar { display: flex; align-items: center; justify-content: space-between; height: 78px; gap: 22px; }
.logo { display: inline-flex; align-items: center; gap: 12px; font-weight: 800; letter-spacing: -0.03em; }
.logo-mark { width: 38px; height: 38px; border-radius: 13px; display: grid; place-items: center; background: linear-gradient(135deg, var(--primary), var(--teal)); color: #061523; box-shadow: 0 0 34px oklch(0.72 0.16 220 / 0.28); }
.logo small { display: block; color: var(--muted); font: 500 11px/1 var(--mono); letter-spacing: .12em; text-transform: uppercase; margin-top: 3px; }
.nav-links { display: flex; align-items: center; gap: 6px; }
.nav-link, .drop-btn { border: 0; color: var(--muted); background: transparent; padding: 10px 12px; border-radius: 12px; cursor: pointer; transition: color .18s ease, background .18s ease; }
.nav-link:hover, .drop-btn:hover, .nav-link.active { color: var(--text); background: oklch(1 0 0 / 0.06); }
.dropdown { position: relative; }
.dropdown-menu { position: absolute; top: calc(100% + 12px); left: 0; min-width: 240px; padding: 8px; border: 1px solid var(--line); border-radius: 18px; background: oklch(0.18 0.04 255 / 0.96); box-shadow: var(--shadow); opacity: 0; transform: translateY(8px); pointer-events: none; transition: opacity .18s ease, transform .18s ease; }
.dropdown:hover .dropdown-menu, .dropdown:focus-within .dropdown-menu { opacity: 1; transform: translateY(0); pointer-events: auto; }
.dropdown-menu a { display: block; padding: 12px 13px; border-radius: 12px; color: var(--muted); }
.dropdown-menu a:hover { color: var(--text); background: oklch(1 0 0 / 0.06); }
.nav-actions { display: flex; align-items: center; gap: 12px; }
.mobile-toggle { display: none; border: 1px solid var(--line); color: var(--text); background: oklch(1 0 0 / 0.04); border-radius: 12px; width: 42px; height: 42px; }

.btn { display: inline-flex; align-items: center; justify-content: center; gap: 9px; min-height: 46px; padding: 0 18px; border-radius: 999px; border: 1px solid transparent; font-weight: 800; cursor: pointer; transition: transform .16s ease, box-shadow .18s ease, background .18s ease, border-color .18s ease; }
.btn:hover { transform: translateY(-2px); }
.btn:active { transform: scale(.98); }
.btn-primary { color: #061523; background: linear-gradient(135deg, var(--primary), var(--teal)); box-shadow: 0 14px 40px oklch(0.68 0.16 210 / 0.28); }
.btn-secondary { color: var(--text); border-color: var(--line); background: oklch(1 0 0 / 0.055); }
.btn-secondary:hover { border-color: var(--line-strong); background: oklch(1 0 0 / 0.08); }
.kicker { color: var(--teal); font: 800 12px/1.3 var(--mono); text-transform: uppercase; letter-spacing: .16em; }
.hero { position: relative; overflow: hidden; padding: 92px 0 62px; }
.hero::before { content: ""; position: absolute; inset: 0; background-image: linear-gradient(oklch(1 0 0 / .055) 1px, transparent 1px), linear-gradient(90deg, oklch(1 0 0 / .055) 1px, transparent 1px); background-size: 56px 56px; mask-image: linear-gradient(to bottom, black, transparent 78%); pointer-events: none; }
.hero-grid { position: relative; display: grid; grid-template-columns: minmax(0, 1.02fr) minmax(340px, .78fr); gap: 48px; align-items: center; }
h1, h2, h3, p { margin-top: 0; }
h1 { font-size: clamp(46px, 7vw, 82px); line-height: .92; letter-spacing: -0.075em; margin-bottom: 22px; }
h2 { font-size: clamp(30px, 4vw, 52px); line-height: 1; letter-spacing: -0.055em; margin-bottom: 16px; }
h3 { font-size: 21px; letter-spacing: -0.025em; margin-bottom: 10px; }
p { color: var(--muted); line-height: 1.72; }
.lead { font-size: clamp(17px, 1.9vw, 21px); max-width: 730px; }
.hero-actions { display: flex; gap: 14px; flex-wrap: wrap; margin-top: 30px; }
.metric-strip { display: flex; gap: 14px; flex-wrap: wrap; margin-top: 32px; }
.mini-metric { flex: 1 1 150px; padding: 14px 16px; border: 1px solid var(--line); border-radius: 18px; background: oklch(1 0 0 / 0.045); }
.mini-metric strong { display: block; font-size: 24px; color: var(--text); }
.mini-metric span { color: var(--soft); font-size: 13px; }

.panel { border: 1px solid var(--line); border-radius: var(--radius); background: linear-gradient(180deg, oklch(1 0 0 / 0.075), oklch(1 0 0 / 0.035)); box-shadow: var(--shadow); }
.visual-card { position: relative; min-height: 440px; padding: 24px; overflow: hidden; }
.visual-card::after { content: ""; position: absolute; inset: auto -20% -35% -20%; height: 58%; background: radial-gradient(closest-side, oklch(0.74 0.15 194 / .22), transparent); }
.data-window { position: relative; z-index: 1; border: 1px solid var(--line); border-radius: 20px; background: oklch(0.13 0.035 255 / .86); padding: 18px; overflow: hidden; }
.window-bar { display: flex; gap: 7px; margin-bottom: 18px; }
.dot { width: 9px; height: 9px; border-radius: 50%; background: var(--primary); opacity: .8; }
.flow-row { display: grid; grid-template-columns: 1fr auto 1fr; gap: 12px; align-items: center; margin: 12px 0; }
.flow-node { padding: 14px; border-radius: 15px; background: oklch(1 0 0 / .055); border: 1px solid var(--line); }
.flow-node strong { display: block; }
.flow-node small { color: var(--soft); }
.arrow { color: var(--teal); }
.sparkline { height: 86px; margin-top: 20px; border-radius: 16px; background: linear-gradient(135deg, oklch(0.72 0.16 220 / .12), transparent), repeating-linear-gradient(90deg, transparent 0 23px, oklch(1 0 0 / .055) 23px 24px); position: relative; overflow: hidden; }
.sparkline svg { position: absolute; inset: 12px 12px 8px; width: calc(100% - 24px); height: calc(100% - 20px); }
.section { padding: 78px 0; }
.section-head { display: flex; align-items: end; justify-content: space-between; gap: 28px; margin-bottom: 30px; }
.section-head p { max-width: 680px; margin-bottom: 0; }
.grid-3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 22px; }
.card { position: relative; padding: 24px; border: 1px solid var(--line); border-radius: 22px; background: oklch(1 0 0 / 0.045); transition: transform .2s ease, border-color .2s ease, background .2s ease; overflow: hidden; }
.card:hover { transform: translateY(-4px); border-color: var(--line-strong); background: oklch(1 0 0 / 0.065); }
.icon { width: 43px; height: 43px; border-radius: 14px; display: grid; place-items: center; color: #061523; background: linear-gradient(135deg, var(--primary), var(--teal)); margin-bottom: 18px; }
.product-banner { padding: 22px; display: flex; justify-content: space-between; align-items: center; gap: 22px; background: linear-gradient(135deg, oklch(0.22 0.07 250), oklch(0.23 0.08 205 / .82)); }
.product-banner strong { font-size: clamp(24px, 3vw, 40px); letter-spacing: -.05em; }

.tabs { display: flex; gap: 8px; flex-wrap: wrap; padding: 6px; border: 1px solid var(--line); border-radius: 999px; background: oklch(1 0 0 / .04); width: fit-content; }
.tab-btn { border: 0; border-radius: 999px; padding: 11px 16px; cursor: pointer; color: var(--muted); background: transparent; transition: background .2s ease, color .2s ease, transform .2s ease; }
.tab-btn:hover { color: var(--text); }
.tab-btn.active { color: #061523; background: linear-gradient(135deg, var(--primary), var(--teal)); font-weight: 800; box-shadow: 0 10px 28px oklch(0.68 0.15 215 / .22); }
.tab-panel { display: none; animation: fadeUp .34s ease both; }
.tab-panel.active { display: block; }
@keyframes fadeUp { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
.industry-shell { display: grid; grid-template-columns: 320px 1fr; gap: 24px; align-items: start; }
.industry-content { min-height: 250px; }
.check-list { list-style: none; padding: 0; margin: 18px 0 0; display: grid; gap: 12px; }
.check-list li { display: flex; gap: 10px; align-items: flex-start; color: var(--muted); }
.check-list i { color: var(--green); flex: 0 0 auto; margin-top: 3px; }

.ecosystem { position: relative; min-height: 430px; display: grid; place-items: center; padding: 34px; overflow: hidden; }
.eco-core { width: 190px; height: 190px; border-radius: 50%; display: grid; place-items: center; text-align: center; background: radial-gradient(circle, oklch(0.72 0.16 220 / .34), oklch(0.18 0.04 255)); border: 1px solid var(--line-strong); box-shadow: 0 0 60px oklch(0.72 0.16 220 / .22); z-index: 2; }
.eco-node { position: absolute; width: min(285px, 34%); padding: 20px; border: 1px solid var(--line); border-radius: 20px; background: oklch(0.16 0.04 255 / .92); z-index: 2; }
.eco-node:nth-child(2) { left: 34px; top: 54px; }
.eco-node:nth-child(3) { right: 34px; top: 54px; }
.eco-node:nth-child(4) { bottom: 44px; left: 50%; transform: translateX(-50%); }
.eco-lines { position: absolute; inset: 0; opacity: .8; }

.stat-rings { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.stat-ring { text-align: center; padding: 26px 18px; }
.ring { width: 158px; height: 158px; margin: 0 auto 16px; border-radius: 50%; display: grid; place-items: center; background: conic-gradient(var(--teal) var(--progress), oklch(1 0 0 / .08) 0); position: relative; }
.ring::after { content: ""; position: absolute; inset: 11px; border-radius: 50%; background: #101d2e; border: 1px solid var(--line); }
.ring strong { position: relative; z-index: 1; font-size: 38px; letter-spacing: -.05em; }
.timeline { display: grid; gap: 18px; }
.timeline-item { display: grid; grid-template-columns: 125px 1fr; gap: 18px; align-items: center; }
.duration { color: var(--teal); font: 800 18px/1 var(--mono); }
.progress { height: 12px; border-radius: 999px; background: oklch(1 0 0 / .08); overflow: hidden; margin-top: 10px; }
.progress span { display: block; height: 100%; width: var(--w); border-radius: inherit; background: linear-gradient(90deg, var(--primary), var(--green)); }
.accordion { display: grid; gap: 12px; }
.accordion-item { border: 1px solid var(--line); border-radius: 18px; overflow: hidden; background: oklch(1 0 0 / .04); }
.accordion-button { width: 100%; border: 0; color: var(--text); background: transparent; padding: 19px 20px; display: flex; justify-content: space-between; align-items: center; cursor: pointer; text-align: left; font-weight: 800; }
.accordion-panel { max-height: 0; overflow: hidden; transition: max-height .28s ease; }
.accordion-panel p { padding: 0 20px 20px; margin: 0; }
.accordion-item.active .accordion-panel { max-height: 180px; }
.accordion-item.active .accordion-button i { transform: rotate(45deg); }
.lifecycle { padding: 28px; }
.lifecycle-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; align-items: stretch; }
.lifecycle-step { border: 1px solid var(--line); border-radius: 18px; padding: 18px; background: oklch(1 0 0 / .045); position: relative; }
.lifecycle-step:not(:last-child)::after { content: ""; position: absolute; right: -16px; top: 50%; width: 16px; height: 2px; background: var(--teal); box-shadow: 0 0 16px var(--teal); }
.product-table { width: 100%; border-collapse: collapse; overflow: hidden; border-radius: 18px; }
.product-table th, .product-table td { padding: 13px 14px; border-bottom: 1px solid var(--line); text-align: left; }
.product-table th { color: var(--teal); font: 800 12px var(--mono); text-transform: uppercase; letter-spacing: .12em; }
.testimonial-viewport { overflow: hidden; }
.testimonial-track { display: flex; transition: transform .38s ease; }
.testimonial-card { flex: 0 0 100%; padding: 30px; }
.dots { display: flex; justify-content: center; gap: 9px; margin-top: 15px; }
.dot-btn { width: 10px; height: 10px; padding: 0; border-radius: 50%; border: 0; background: oklch(1 0 0 / .28); cursor: pointer; }
.dot-btn.active { background: var(--teal); transform: scale(1.2); }

.security-matrix { display: grid; grid-template-columns: 1.1fr .9fr; gap: 24px; align-items: center; }
.matrix { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }
.matrix-cell { padding: 16px; min-height: 112px; border-radius: 18px; border: 1px solid var(--line); background: linear-gradient(135deg, oklch(0.72 0.16 220 / .1), oklch(1 0 0 / .035)); }
.integration-diagram { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.integration-pipe { padding: 24px; text-align: center; border: 1px solid var(--line); border-radius: 20px; background: oklch(1 0 0 / .045); }
.integration-pipe i { color: var(--teal); }

.demo-shell { display: grid; grid-template-columns: .82fr 1.18fr; gap: 28px; align-items: start; }
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
.field.full { grid-column: 1 / -1; }
label { display: block; color: var(--muted); font-weight: 700; font-size: 13px; margin-bottom: 8px; }
input, select, textarea { width: 100%; color: var(--text); background: oklch(0.13 0.035 255 / .76); border: 1px solid var(--line); border-radius: 14px; padding: 13px 14px; outline: none; transition: border-color .18s ease, box-shadow .18s ease; }
textarea { resize: vertical; min-height: 118px; }
input:focus, select:focus, textarea:focus { border-color: var(--teal); box-shadow: 0 0 0 4px oklch(0.72 0.16 220 / .14); }
.error { display: none; color: oklch(0.78 0.17 28); font-size: 12px; margin-top: 6px; }
.field.invalid input, .field.invalid select, .field.invalid textarea { border-color: oklch(0.73 0.19 28); }
.field.invalid .error { display: block; }
.form-success { display: none; padding: 14px 16px; border: 1px solid oklch(0.76 0.17 145 / .5); border-radius: 14px; background: oklch(0.76 0.17 145 / .1); color: var(--text); margin-bottom: 16px; }

.cookie-banner { position: fixed; left: 18px; right: 18px; bottom: 18px; z-index: 70; display: none; }
.cookie-inner { width: min(940px, 100%); margin: 0 auto; padding: 18px; display: flex; gap: 18px; align-items: center; justify-content: space-between; }
.cookie-inner p { margin: 0; }
.footer { padding: 58px 0 34px; border-top: 1px solid var(--line); background: oklch(0.1 0.028 255 / .58); }
.footer-grid { display: grid; grid-template-columns: 1.6fr repeat(4, 1fr); gap: 26px; }
.footer h4 { margin: 0 0 12px; font-size: 13px; color: var(--teal); text-transform: uppercase; letter-spacing: .13em; font-family: var(--mono); }
.footer a { display: block; color: var(--muted); padding: 5px 0; }
.footer a:hover { color: var(--text); }
.footer-bottom { display: flex; justify-content: space-between; gap: 18px; color: var(--soft); border-top: 1px solid var(--line); padding-top: 22px; margin-top: 32px; font-size: 13px; }

@media (max-width: 920px) {
  .mobile-toggle { display: inline-grid; place-items: center; }
  .nav-links { position: fixed; left: 18px; right: 18px; top: 88px; display: none; flex-direction: column; align-items: stretch; padding: 16px; border: 1px solid var(--line); border-radius: 20px; background: oklch(0.15 0.04 255 / .98); box-shadow: var(--shadow); }
  .nav-links.open { display: flex; }
  .dropdown-menu { position: static; min-width: 0; opacity: 1; transform: none; pointer-events: auto; display: none; margin-top: 4px; box-shadow: none; }
  .dropdown.open .dropdown-menu, .dropdown:focus-within .dropdown-menu { display: block; }
  .hero-grid, .industry-shell, .security-matrix, .demo-shell { grid-template-columns: 1fr; }
  .grid-3, .stat-rings, .integration-diagram { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .lifecycle-grid { grid-template-columns: repeat(2, 1fr); }
  .lifecycle-step::after { display: none; }
}
@media (max-width: 640px) {
  .container { width: min(100% - 24px, 1180px); }
  .hero { padding: 58px 0 42px; }
  .navbar { height: 68px; }
  .nav-actions .btn { display: none; }
  .grid-2, .grid-3, .stat-rings, .integration-diagram, .form-grid, .lifecycle-grid { grid-template-columns: 1fr; }
  .section-head, .product-banner, .cookie-inner, .footer-bottom { flex-direction: column; align-items: flex-start; }
  .tabs { border-radius: 18px; width: 100%; }
  .tab-btn { flex: 1 1 auto; }
  .ecosystem { min-height: auto; display: block; }
  .eco-core { margin: 0 auto 16px; width: 150px; height: 150px; }
  .eco-node { position: static; width: 100%; transform: none !important; margin-top: 12px; }
  .eco-lines { display: none; }
  .timeline-item { grid-template-columns: 1fr; }
  .visual-card { min-height: auto; }
  .flow-row { grid-template-columns: 1fr; }
  .arrow { transform: rotate(90deg); text-align: center; }
  .footer-grid { grid-template-columns: 1fr; }
}
EOF

cat > /app/output/assets/app.js <<'EOF'
(function () {
  const qs = (sel, root = document) => root.querySelector(sel);
  const qsa = (sel, root = document) => Array.from(root.querySelectorAll(sel));

  qsa('[data-icon]').forEach((el) => {
    const name = el.getAttribute('data-icon');
    const map = {
      menu: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 6h16M4 12h16M4 18h16"/></svg>',
      arrow: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M13 5l7 7-7 7"/></svg>',
      check: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M20 6 9 17l-5-5"/></svg>',
      plus: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg>',
      shield: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/></svg>',
      database: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 1.7 4 3 9 3s9-1.3 9-3V5"/><path d="M3 12c0 1.7 4 3 9 3s9-1.3 9-3"/></svg>',
      activity: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>',
      map: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m9 18-6 3V6l6-3 6 3 6-3v15l-6 3-6-3Z"/><path d="M9 3v15M15 6v15"/></svg>',
      lock: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>',
      plug: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22v-5M9 8V2M15 8V2M6 8h12v4a6 6 0 0 1-12 0V8Z"/></svg>'
    };
    el.innerHTML = map[name] || map.arrow;
  });

  const mobileToggle = qs('.mobile-toggle');
  const navLinks = qs('.nav-links');
  if (mobileToggle && navLinks) {
    mobileToggle.addEventListener('click', () => navLinks.classList.toggle('open'));
  }
  qsa('.drop-btn').forEach((btn) => btn.addEventListener('click', () => btn.closest('.dropdown').classList.toggle('open')));

  qsa('[data-tabs]').forEach((tabsRoot) => {
    const buttons = qsa('[data-tab]', tabsRoot);
    const scope = tabsRoot.getAttribute('data-tabs');
    const panels = qsa(`[data-tab-panel][data-tab-scope="${scope}"]`);
    buttons.forEach((button) => {
      button.addEventListener('click', () => {
        const target = button.getAttribute('data-tab');
        buttons.forEach((b) => b.classList.toggle('active', b === button));
        panels.forEach((panel) => panel.classList.toggle('active', panel.getAttribute('data-tab-panel') === target));
      });
    });
  });

  qsa('.accordion').forEach((accordion) => {
    qsa('.accordion-item', accordion).forEach((item, index) => {
      const button = qs('.accordion-button', item);
      button.addEventListener('click', () => {
        qsa('.accordion-item', accordion).forEach((other) => other.classList.toggle('active', other === item));
      });
      if (index === 0) item.classList.add('active');
    });
  });

  qsa('[data-carousel]').forEach((carousel) => {
    const track = qs('.testimonial-track', carousel);
    const dots = qsa('.dot-btn', carousel);
    dots.forEach((dot, index) => {
